/**
 * Copies every live issue of `fromProjectId` into `toProjectId` for
 * `ProjectService.cloneProject`: renumbered from 1 in the source issues'
 * number order, reset to `defaultStatus`, unassigned, with no start or
 * completion time, authored by the person cloning. Labels come along;
 * comments, attachments and the `parentId` link do not.
 */
export async function copyLiveIssuesForClone(
  orgId: OrgId,
  fromProjectId: ProjectId,
  toProjectId: ProjectId,
  authorId: UserId,
  defaultStatus: IssueStatus,
): Promise<readonly Issue[]> {
  const db = getDb();

  const rows = db
    .select()
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        eq(issues.projectId, fromProjectId),
        isNull(issues.archivedAt),
      ),
    )
    .orderBy(issues.number)
    .all();

  if (rows.length === 0) return [];

  const labels = await listLabelsForIssues(
    orgId,
    rows.map((row) => row.id as IssueId),
  );
  const stamp = toIsoTimestamp(new Date());

  return rows.map((row, index) => {
    const id = newId();
    const labelIds = (labels[row.id] ?? []).map((label) => label.id);

    db.insert(issues)
      .values({
        id,
        orgId,
        projectId: toProjectId,
        number: index + 1,
        title: row.title,
        description: row.description,
        status: defaultStatus,
        priority: row.priority,
        authorId,
        assigneeId: null,
        parentId: null,
        estimate: row.estimate,
        dueAt: row.dueAt,
        startedAt: null,
        completedAt: null,
        createdAt: stamp,
        updatedAt: stamp,
      })
      .run();

    if (labelIds.length > 0) {
      db.insert(issueLabels)
        .values(labelIds.map((labelId) => ({ orgId, issueId: id, labelId })))
        .run();
    }

    return toIssue(
      {
        ...row,
        id,
        projectId: toProjectId,
        number: index + 1,
        status: defaultStatus,
        authorId,
        assigneeId: null,
        parentId: null,
        startedAt: null,
        completedAt: null,
        createdAt: stamp,
        updatedAt: stamp,
      },
      labelIds,
    );
  });
}

